def page(route,title,body):
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if route==key else '')+f'>{label}</a>' for key,url,label in [('home','/','Overview'),('work','/work/','My Projects'),('clients','/clients/','Client work'),('social','/social/','Social Media')])
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Euan Garcia — CG generalist and video editor. Explore animation, moving image and client collaborations."><title>{title} — Euan Garcia | CG & Video</title><link rel="icon" type="image/svg+xml" href="{favicon}"><link rel="stylesheet" href="/styles.css"></head><body><div class="wrap"><header><a class="brand" href="/" aria-label="Portfolio home">Euan Garcia<span> /</span></a><nav aria-label="Main navigation">{nav}</nav></header><main>{body}</main><footer><span>Euan Garcia · CG generalist & video editor</span><span>Portfolio in progress · More work coming soon</span></footer></div></body></html>'''
    dest=root/('index.html' if route=='home' else route+'/index.html');dest.parent.mkdir(exist_ok=True,parents=True);dest.write_text(html.replace('</body>', '<script src="/projects.js" defer></script></body>') if route in ('work','clients') else html)
def placeholder(n,label,bottom='Project space · Media to come',light=False):
    return f'<div class="placeholder {"light" if light else ""}"><span class="tag">{label}</span><span class="number">{n}</span><span class="bottom">{bottom}</span></div>'

